class Solution:
    def matrixReshape(self, mat: list[list[int]], r: int, c: int) -> list[list[int]]:
        if len(mat) * len(mat[0]) != r * c:
            return mat
        flat = [value for row in mat for value in row]
        return [flat[i:i + c] for i in range(0, len(flat), c)]
